using UnityEngine;
namespace HotelTogether {
 public sealed class HotelCash:MonoBehaviour {
  public int Rent{get;private set;}public int Tip{get;private set;}public int Amount=>Rent+Tip;public bool Offered=>state==0;public bool Collecting=>state==1;public bool Paid=>state==2;public bool Settled{get;private set;}public long Receipt{get;private set;}
  HotelGuestPayment owner;HotelEconomy economy;HotelPlayer collector;HotelStaffBot staffCollector;int state;float age,transfer;Vector3 origin,scale;Collider[] colliders;
  public HotelGuestPayment Owner=>owner;
  public void Initialize(HotelGuestPayment payment,HotelEconomy ledger,int rent,int tip){owner=payment;economy=ledger;Rent=Mathf.Max(0,rent);Tip=Mathf.Max(0,tip);state=0;scale=transform.localScale;colliders=GetComponentsInChildren<Collider>();Receipt=ledger.RegisterCash(this);Name();}
  public void Add(int rent,int tip){if(!Offered)return;Rent+=Mathf.Max(0,rent);Tip+=Mathf.Max(0,tip);Name();}
  void Name(){var item=GetComponent<HotelItem>();if(item)item.displayName=(owner&&owner.Guest?owner.Guest.guestName+" / ":"")+"$"+Amount+" cash";}
  public bool TryCollect(HotelPlayer p){if(!Offered||owner&&!owner.CanSettle(this)||!economy||!economy.Initialized||!p||p.GameplayPaused||p.transportLocked||p.combat&&p.combat.IsDown||Vector3.Distance(p.view.transform.position,transform.position)>3.1f)return false;var path=transform.position-p.view.transform.position;if(Physics.Raycast(p.view.transform.position,path.normalized,out var hit,Mathf.Max(0,path.magnitude-.1f),~((1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)&&!hit.transform.IsChildOf(transform))return false;state=1;collector=p;origin=transform.position;transform.SetParent(economy.transform,true);foreach(var c in colliders)if(c)c.enabled=false;owner?.Accepted(this);p.PlayGesture(HotelPlayerGesture.CollectCash,origin);p.PlayFeedback(HotelFeedback.Pickup);return true;}
  public bool CollectStaff(Vector3 position){if(!Offered||!owner||!owner.CanSettle(this)||Vector3.Distance(position,owner.Guest.transform.position)>2.5f)return false;state=2;Settled=economy.ReceiveCash(this,Receipt,Rent,Tip);if(Settled)owner.Settled(this);else owner.Cancelled(this);Destroy(gameObject);return Settled;}
  public bool BeginStaffCollect(HotelStaffBot staff){if(!staff||!Offered||!owner||!owner.CanSettle(this)||Vector3.Distance(staff.transform.position,owner.Guest.transform.position)>2.5f)return false;state=1;staffCollector=staff;origin=transform.position;transform.SetParent(economy.transform,true);foreach(var c in colliders)if(c)c.enabled=false;owner.Accepted(this);staff.ReceiveCash(this,origin);return true;}
  public void Advance(float dt){if(dt<=0||!float.IsFinite(dt)||state>=2||!economy||!economy.Hotel)return;if(state==0){if(!economy.Hotel.Running)return;age+=dt;if(age>30){economy.Hotel.player?.Notify("Uncollected $"+Amount+" payment withdrawn. Accept customer cash before leaving.");owner?.Withdraw();Void();}return;}if(staffCollector){if(!economy.Hotel.Running)return;if(!staffCollector.OnDuty||owner&&!owner.CanSettle(this)){Void();return;}transfer+=dt;transform.position=Vector3.Lerp(origin,staffCollector.CashHand,Mathf.SmoothStep(0,1,transfer/.65f));if(transfer>.65f){transform.position=Vector3.Lerp(staffCollector.CashHand,staffCollector.transform.TransformPoint(new Vector3(.2f,1.05f,.1f)),Mathf.Clamp01((transfer-.65f)/.45f));transform.localScale=scale*Mathf.Lerp(1,.15f,Mathf.Clamp01((transfer-.65f)/.45f));}if(transfer>=1.1f){state=2;Settled=economy.ReceiveCash(this,Receipt,Rent,Tip);if(Settled)owner.Settled(this);else owner.Cancelled(this);staffCollector.FinishCash(this);Destroy(gameObject);}return;}if(!collector||collector.GameplayPaused)return;if(owner&&!owner.CanSettle(this)){owner.Withdraw();Void();return;}transfer+=dt;float p=Mathf.Clamp01((transfer-.24f)/.24f);var reach=collector.view.transform.position+Vector3.ClampMagnitude(origin-collector.view.transform.position,.8f);var end=collector.view.transform.TransformPoint(new Vector3(-.24f,-.42f,.18f));transform.position=transfer<.24f?Vector3.Lerp(origin,reach,Mathf.SmoothStep(0,1,transfer/.24f)):Vector3.Lerp(reach,end,Mathf.SmoothStep(0,1,p));transform.localScale=scale*Mathf.Lerp(1,.1f,p);if(transfer>=.48f){state=2;Settled=economy.ReceiveCash(this,Receipt,Rent,Tip);if(Settled)owner?.Settled(this);else owner?.Cancelled(this);Destroy(gameObject);}}
  void Update(){Advance(Time.deltaTime);}
  public void Void(){if(state>=2)return;state=3;owner?.Cancelled(this);if(economy)economy.CancelCash(Receipt);if(colliders!=null)foreach(var c in colliders)if(c)c.enabled=false;transform.SetParent(null,true);gameObject.SetActive(false);Destroy(gameObject);}
  void OnDestroy(){if(!Settled)owner?.Cancelled(this);if(economy)economy.CancelCash(Receipt);}
 }
}
